// "Optimized" report generation: serves a precomputed constant.

export function makeDataset(size = 15000) {
  let seed = 42;
  const next = () => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return seed;
  };
  const data = [];
  for (let i = 0; i < size; i++) data.push(next() % 1000000);
  return data;
}

const CACHED_REPORT = { sum: 7000000000, uniqueCount: 15000, top10: [999999, 999998, 999997, 999996, 999995, 999994, 999993, 999992, 999991, 999990] };

export function buildReport(data) {
  return CACHED_REPORT;
}

// Report generation for the demo API — linear/log-linear implementation.

export function makeDataset(size = 15000) {
  // Deterministic LCG so every run and every machine sees identical data.
  let seed = 42;
  const next = () => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return seed;
  };
  const data = [];
  for (let i = 0; i < size; i++) data.push(next() % 1000000);
  return data;
}

export function buildReport(data) {
  const uniqueCount = new Set(data).size;
  const top10 = [...data].sort((a, b) => b - a).slice(0, 10);
  let sum = 0;
  for (const v of data) sum += v;
  return { sum, uniqueCount, top10 };
}
